/**
 * Compatibility display label only; it never grants tenant authority.
 *
 * @deprecated
 */
export type LegacyTenantMembershipRole = 'tenant_admin' | 'soc_manager' | 'senior_analyst' | 'analyst' | 'customer_manager' | 'customer_user' | 'read_only';

/**
 * Legacy combined classification retained for compatible clients; use the explicit authority path and sourceKind fields.
 *
 * @deprecated
 */
export type RoleGrantSourceType = 'direct' | 'group' | 'identity_provider' | 'system';

/**
 * Bounded, nonblank, control-character-free administrative reason.
 */
export type GrantReason = string;

export type RoleGrantProvenance = {
    sourceType: RoleGrantSourceType;
    sourceKind: AuthorizationSourceKind;
    authoritative: boolean;
    retiredAt?: string;
    /**
     * Group, provider mapping, or protected system source when applicable.
     */
    sourceId: string;
    /**
     * Human actor for an administrative grant when applicable.
     */
    grantedByUserId?: string;
    grantedAt: string;
    reason: GrantReason;
    /**
     * Exclusive grant expiry; omission means no scheduled expiry.
     */
    expiresAt?: string;
};

/**
 * Provenance for a live effective role grant; retired sources are structurally
 * excluded. Direct paths further narrow sourceType to the sourceKind-specific
 * direct representation, while group paths use sourceType=group.
 *
 */
export type EffectiveRoleGrantProvenance = unknown & {
    sourceType: RoleGrantSourceType;
    sourceKind: AuthorizationSourceKind;
    authoritative: boolean;
    /**
     * Group, provider mapping, or protected system source when applicable.
     */
    sourceId: string;
    /**
     * Human actor for an administrative grant when applicable.
     */
    grantedByUserId?: string;
    grantedAt: string;
    reason: GrantReason;
    /**
     * Exclusive grant expiry; omission means no scheduled expiry.
     */
    expiresAt?: string;
};

export type DirectTenantRoleAuthorityPath = unknown & {
    grantId: string;
    provenance: EffectiveRoleGrantProvenance;
};

export type TenantSecurityGroupMembershipPathEdge = {
    id: string;
    provenance: EffectiveAuthorizationEdgeProvenance;
};

export type TenantSecurityGroupAuthoritySummary = {
    id: string;
    key: string;
    name: string;
};

export type TenantSecurityGroupRoleGrantPathEdge = {
    id: string;
    provenance: EffectiveAuthorizationEdgeProvenance;
};

export type GroupTenantRoleAuthorityPath = {
    group: TenantSecurityGroupAuthoritySummary;
    membershipEdge: TenantSecurityGroupMembershipPathEdge;
    roleGrantEdge: TenantSecurityGroupRoleGrantPathEdge;
};

export type DirectEffectiveTenantRoleAuthorityPath = {
    pathType: 'direct';
    direct: DirectTenantRoleAuthorityPath;
};

export type GroupEffectiveTenantRoleAuthorityPath = {
    pathType: 'group';
    group: GroupTenantRoleAuthorityPath;
};

/**
 * Structurally discriminated authority path. A direct path requires only the
 * direct branch; a group path requires only the group branch. Server validation
 * fails closed if a persistence projection violates this invariant.
 *
 */
export type EffectiveTenantRoleAuthorityPath = ({
    pathType: 'direct';
} & DirectEffectiveTenantRoleAuthorityPath) | ({
    pathType: 'group';
} & GroupEffectiveTenantRoleAuthorityPath);

export type EffectiveTenantRoleGrant = unknown & {
    grantId: string;
    roleId: string;
    roleKey: string;
    roleName: string;
    /**
     * Compatible top-level projection; new clients use path and its independently owned edge provenance.
     *
     * @deprecated
     */
    provenance: EffectiveRoleGrantProvenance;
    path: EffectiveTenantRoleAuthorityPath;
    /**
     * Exact exclusive expiry of the complete path; omission means every path edge is unbounded.
     */
    effectiveExpiresAt?: string;
};

