export type DirectUserRoleGrantRequest = {
    roleId: string;
    reason: GrantReason;
    /**
     * Exclusive future expiry; omission creates a non-expiring direct grant.
     * When present, the instant must resolve exactly to PostgreSQL microsecond
     * precision; non-zero precision finer than one microsecond, a UTC-normalized
     * year outside 0000 through 9999, leap-second notation (`:60`), or an
     * explicit null is invalid.
     *
     */
    expiresAt?: string;
};

