/**
 * Closed tenant ticket aggregate kind with an independent policy and counter namespace.
 */
export type TicketNumberingKind = 'alert' | 'case';

export type TicketNumberingSeparator = '-' | '/' | '.' | '_';

/**
 * Annual resets the counter namespace by UTC year; lifetime uses period key zero.
 */
export type TicketNumberingPeriod = 'annual' | 'lifetime';

export type TicketNumberingDraft = unknown & {
    prefix: string;
    separator: TicketNumberingSeparator;
    period: TicketNumberingPeriod;
    width: number;
    /**
     * Initial lower bound for a fresh namespace or annual period; lowering it never rewinds a durable counter.
     */
    start: number;
};

export type TicketNumberingPublisher = unknown & {
    type: 'system' | 'membership';
    /**
     * Exact publishing tenant-membership UUID for human publications; null only for system-installed defaults.
     */
    membershipId: string | null;
};

export type TicketNumberingPolicy = {
    versionId: string;
    tenantId: string;
    kind: TicketNumberingKind;
    version: ResourceVersion;
    prefix: string;
    separator: TicketNumberingSeparator;
    period: TicketNumberingPeriod;
    width: number;
    start: number;
    publisher: TicketNumberingPublisher;
    publishedAt: string;
};

/**
 * Exact expected current version plus one complete replacement draft; no field inherits implicitly.
 */
export type TicketNumberingUpdateRequest = unknown & {
    /**
     * Must equal the positive version encoded by the strong If-Match value.
     */
    expectedVersion: number;
    prefix: string;
    separator: TicketNumberingSeparator;
    period: TicketNumberingPeriod;
    width: number;
    start: number;
};

export type TicketNumberingPreview = {
    tenantId: string;
    kind: TicketNumberingKind;
    prefix: string;
    separator: TicketNumberingSeparator;
    period: TicketNumberingPeriod;
    width: number;
    start: number;
    maximumSequence: number;
    /**
     * Server UTC instant used for this preview.
     */
    at: string;
    /**
     * Zero for lifetime numbering, otherwise the UTC year in the 2000–9999 range.
     */
    periodKey: number;
    /**
     * The draft's start value rendered without reserving or allocating it.
     */
    example: string;
};

/**
 * The immutable published policy and exact replay status; the replay field must agree with X-Idempotent-Replay.
 */
export type TicketNumberingMutationResult = {
    policy: TicketNumberingPolicy;
    replayed: boolean;
};

