/**
 * Non-secret tenant OIDC configuration. Callback, discovery, JWKS, client secret, token, claim, and subject material are structurally absent.
 */
export type TenantFederationOidcCreateConfiguration = unknown & {
    /**
     * Exact canonical HTTPS issuer; discovery endpoints remain server-derived and SSRF-filtered.
     */
    issuer: string;
    /**
     * Exact client identifier without Unicode whitespace or control characters.
     */
    clientId: string;
    /**
     * Must exactly equal PublicOrigin plus `/signed-out`, the deployment-owned post-logout return URI.
     */
    postLogoutRedirectUri: string;
    extraScopes: Array<string>;
    /**
     * Requires exact `offline_access` membership in extraScopes and admits only the encrypted session-scoped rotation lifecycle; it never extends the local absolute session lifetime.
     */
    allowRefreshToken: boolean;
    /**
     * Mapping replacement and provider enablement require true exactly when at least one UserInfo extraction rule exists. Enabling additionally requires a canonical UserInfo endpoint in the pinned discovery document; a provider that remains disabled may temporarily stage the flag while configured stays false.
     */
    useUserInfo: boolean;
};

/**
 * Non-secret tenant SAML policy. Metadata, certificates, private keys, assertions, attributes, and subjects are structurally absent.
 */
export type TenantFederationSamlCreateConfiguration = {
    /**
     * Exact IdP entity ID. It must differ from the deployment-derived Periapsis SP entity ID.
     */
    expectedEntityId: string;
    redirectSignatureAlgorithm: 'http://www.w3.org/2001/04/xmldsig-more#rsa-sha256' | 'http://www.w3.org/2001/04/xmldsig-more#rsa-sha384' | 'http://www.w3.org/2001/04/xmldsig-more#rsa-sha512' | 'http://www.w3.org/2001/04/xmldsig-more#ecdsa-sha256' | 'http://www.w3.org/2001/04/xmldsig-more#ecdsa-sha384' | 'http://www.w3.org/2001/04/xmldsig-more#ecdsa-sha512';
    signaturePolicy: 'signed_assertion' | 'signed_response' | 'both';
    /**
     * Fail-closed until a write-only SP-key rotation boundary installs exact tenant/provider keys.
     */
    encryptionPolicy: 'disabled';
    requestedAuthnContexts: Array<string>;
    subjectSource: 'persistent_nameid' | 'immutable_attribute';
    /**
     * Required only for immutable_attribute and null for persistent_nameid.
     */
    subjectAttributeName: string | null;
    /**
     * Required only for immutable_attribute and null for persistent_nameid.
     */
    subjectAttributeNameFormat: string | null;
    clockSkewSeconds: number;
    maxAuthenticationAgeSeconds: number;
};

