/**
 * Server-side discovery/JWKS refresh policy; no caller-supplied endpoint or trust document is accepted. When the current provider enables UserInfo, the pinned discovery document must expose one canonical HTTPS UserInfo endpoint or the refresh fails atomically.
 */
export type TenantOidcTrustDocumentsRefreshRequest = {
    clientAuthentication: 'client_secret_basic' | 'client_secret_post';
    signingAlgorithms: Array<'RS256' | 'RS384' | 'RS512' | 'PS256' | 'PS384' | 'PS512' | 'ES256' | 'ES384' | 'ES512' | 'EdDSA'>;
    reason: string;
};

/**
 * Exact OIDC extraction rule. Scalar, profile, and groups rules cannot name reserved security claims (`iss`, `sub`, `aud`, `azp`, `exp`, `iat`, `nbf`, `auth_time`, `nonce`, `at_hash`, `acr`, or `amr`). A username profile rule and standard id_token AMR rule are mandatory; groups, ACR, and AMR are singleton kinds per source, and ACR/AMR are accepted only from id_token under their standard names.
 */
export type TenantFederationOidcClaimRule = {
    source: 'id_token' | 'userinfo';
    kind: 'scalar' | 'profile' | 'groups' | 'acr' | 'amr';
    claimName: string;
    profileField?: 'username' | 'email' | 'display_name' | null;
    required: boolean;
};

/**
 * Exact SAML attribute extraction rule. NameID subject selection remains in provider configuration; JIT requires one username profile attribute.
 */
export type TenantFederationSamlAttributeRule = {
    kind: 'scalar' | 'profile' | 'groups';
    attributeName: string;
    attributeNameFormat: string;
    profileField?: 'username' | 'email' | 'display_name' | null;
    required: boolean;
};

