export type TenantLdapAuthProviderDiagnostic = ({
    outcome?: 'success';
    category?: 'success';
    endpointPriority?: number;
    stale?: false;
} | {
    outcome?: 'inconclusive';
    category?: 'stale_configuration';
    stale?: true;
    /**
     * Historical priority from the tested snapshot when one can still be safely attributed; otherwise null.
     */
    endpointPriority?: number | null;
} | {
    outcome?: 'failure';
    category?: 'cancelled';
    endpointPriority?: null;
    stale?: false;
} | {
    outcome?: 'failure';
    category?: 'dns_failed' | 'destination_blocked' | 'connect_timeout' | 'connect_failed' | 'tls_failed' | 'certificate_rejected' | 'bind_rejected' | 'protocol_failed';
    endpointPriority?: number;
    stale?: false;
}) & {
    /**
     * Server-generated UUIDv7 diagnostic-run identifier.
     */
    testRunId: string;
    outcome: 'success' | 'failure' | 'inconclusive';
    /**
     * Sanitized non-oracular category; raw directory, network, certificate, and credential errors are never returned.
     */
    category: 'success' | 'dns_failed' | 'destination_blocked' | 'connect_timeout' | 'connect_failed' | 'tls_failed' | 'certificate_rejected' | 'bind_rejected' | 'protocol_failed' | 'cancelled' | 'stale_configuration';
    /**
     * Null when no endpoint can safely be attributed (always for cancellation); stale configuration may retain the bounded historical priority from the tested snapshot.
     */
    endpointPriority: number | null;
    durationMs: number;
    /**
     * True when the tested snapshot no longer matches current provider state.
     */
    stale: boolean;
    completedAt: string;
};

/**
 * Bounded non-secret reason recorded only in redacted audit metadata.
 */
export type TenantLdapMutationReason = string;

/**
 * Human-authored non-secret notes; never interpolated into LDAP operations.
 */
export type TenantLdapNotes = string;

