export type TenantLdapMappingDryRunResult = {
    /**
     * Server-generated UUIDv7 non-mutating evaluation identifier.
     */
    dryRunId: string;
    outcome: 'success' | 'failure' | 'inconclusive';
    decision: 'allow' | 'deny';
    identityDisposition: 'existing_identity' | 'create' | 'deny' | 'unresolved';
    /**
     * False prevents every absence-derived authoritative revoke action.
     */
    observationComplete: boolean;
    /**
     * Stable redacted categories only; no directory values or upstream errors.
     */
    denialReasons: Array<'binding_disabled' | 'provider_disabled' | 'identity_not_found' | 'identity_ambiguous' | 'identity_collision' | 'entry_disabled' | 'jit_disabled' | 'existing_identity_required' | 'no_mapping_match' | 'delegated_authority_denied' | 'assignment_epoch_inactive' | 'stale_snapshot' | 'incomplete_observation' | 'directory_unavailable' | 'local_identity_disabled' | 'tenant_membership_inactive'>;
    matchedMappingIds: Array<string>;
    snapshot: TenantLdapPinnedPlannerSnapshot;
    plan: TenantLdapMappingDryRunPlan;
    generatedAt: string;
};

export type TenantLdapSyncRunState = 'queued' | 'enumerating' | 'applying' | 'succeeded' | 'failed' | 'cancelled' | 'stale';

export type TenantLdapSyncEnumeration = ({
    state?: 'not_started';
    complete?: false;
    truncated?: false;
    absenceBasedRevocationAllowed?: false;
} | {
    state?: 'enumerating';
    complete?: false;
    truncated?: false;
    absenceBasedRevocationAllowed?: false;
} | {
    state?: 'complete';
    complete?: true;
    truncated?: false;
    cursorState?: 'terminal';
} | {
    state?: 'truncated';
    complete?: false;
    truncated?: true;
    absenceBasedRevocationAllowed?: false;
} | {
    state?: 'incomplete';
    complete?: false;
    truncated?: false;
    absenceBasedRevocationAllowed?: false;
}) & {
    state: 'not_started' | 'enumerating' | 'complete' | 'truncated' | 'incomplete';
    complete: boolean;
    truncated: boolean;
    /**
     * May be true only for complete, non-truncated enumeration and an authoritative source; every other state fixes it false.
     */
    absenceBasedRevocationAllowed: boolean;
    entryCount: number;
    pageCount: number;
    responseBytes: number;
    /**
     * State only; raw LDAP paging cookies are never exposed.
     */
    cursorState: 'none' | 'present' | 'terminal' | 'discarded';
    /**
     * Stable sanitized category; raw customer values and upstream errors are forbidden.
     */
    errorCategory: null | 'cancelled' | 'timeout' | 'destination_blocked' | 'directory_unavailable' | 'referral_rejected' | 'duplicate_subject' | 'limit_exceeded' | 'parse_failed' | 'stale_snapshot' | 'worker_interrupted' | 'protocol_failed';
};

