export type ServiceAccountCredentialPermissionGrant = {
    permissionKey: ServiceAccountCredentialPermissionKey;
    scope: ServiceAccountCredentialScope;
};

/**
 * Canonical PostgreSQL CIDR without a zone identifier; duplicate normalized networks are rejected.
 */
