/**
 * Mandatory expiry strictly after issuance and no more than 90 days after issuance.
 */
export type ServiceAccountCredentialExpiry = string;

export type ServiceAccountCredentialState = 'active' | 'expired' | 'revoked';

/**
 * Redacted metadata representation; bearer token, locator, and digest are structurally absent.
 */
export type ServiceAccountCredential = unknown & ({
    lastUsedAt: unknown;
    lastUsedIp: unknown;
} | unknown) & {
    id: string;
    tenantId: string;
    serviceAccountId: string;
    label: string;
    state: ServiceAccountCredentialState;
    issuedByMembershipId: string;
    issuedAt: string;
    expiresAt: ServiceAccountCredentialExpiry;
    rotatedFromCredentialId?: string;
    revokedAt?: string;
    revokedByUserId?: string;
    revokeReason?: GrantReason;
    lastUsedAt?: string;
    lastUsedIp?: unknown | unknown;
    permissions: [
        ServiceAccountCredentialPermissionGrant
    ];
    /**
     * Empty means any trusted resolved client address; otherwise at least one CIDR must contain it. Non-empty responses are in PostgreSQL cidr order (IPv4 before IPv6, then network address and prefix length).
     */
    allowedNetworks: Array<ServiceAccountCredentialCidr>;
    etag: StrongEntityTag;
    version: ResourceVersion;
    updatedAt: string;
};

export type ServiceAccountCredentialList = {
    items: Array<ServiceAccountCredential>;
    nextCursor?: string;
};

export type ServiceAccountCredentialIssueRequest = {
    label: string;
    expiresAt: ServiceAccountCredentialExpiry;
    permissions: [
        ServiceAccountCredentialPermissionGrant
    ];
    /**
     * Empty means unrestricted by source network after trusted-proxy address resolution. The server validates canonical CIDR spelling and normalizes non-empty entries into PostgreSQL cidr order before idempotency binding.
     */
    allowedNetworks: Array<ServiceAccountCredentialCidr>;
};

export type ServiceAccountCredentialRotateRequest = {
    label: string;
    expiresAt: ServiceAccountCredentialExpiry;
    permissions: [
        ServiceAccountCredentialPermissionGrant
    ];
    /**
     * Empty means unrestricted by source network after trusted-proxy address resolution. The server validates canonical CIDR spelling and normalizes non-empty entries into PostgreSQL cidr order before idempotency binding.
     */
    allowedNetworks: Array<ServiceAccountCredentialCidr>;
    revokeReason: GrantReason;
};

export type ServiceAccountCredentialRevokeRequest = {
    reason: GrantReason;
};

/**
 * Opaque canonical bearer envelope returned exactly once; never log or persist it client-side.
 */
export type ServiceAccountBearerToken = string;

/**
 * Secret-bearing one-time representation used only by successful issue and rotation responses.
 */
export type ServiceAccountCredentialSecret = {
    credential: ServiceAccountCredential;
    bearerToken: ServiceAccountBearerToken;
};

