export type WorkflowEffect = 'activity' | 'audit' | 'sla' | 'notification';

/**
 * Closed declarative side-effect set. Activity and audit are mandatory; this plan never grants permission.
 */
export type WorkflowEffectPlan = Array<WorkflowEffect>;

export type WorkflowConditionField = string;

export type WorkflowConditionOperator = 'equal' | 'not_equal' | 'in' | 'not_in' | 'less_than' | 'less_than_or_equal' | 'greater_than' | 'greater_than_or_equal' | 'exists' | 'not_exists';

export type WorkflowConditionValue = ({
    type: 'text';
} & WorkflowTextConditionValue) | ({
    type: 'number';
} & WorkflowNumberConditionValue) | ({
    type: 'boolean';
} & WorkflowBooleanConditionValue) | ({
    type: 'instant';
} & WorkflowInstantConditionValue);

export type WorkflowTextConditionValue = {
    type: 'text';
    value: string;
};

export type WorkflowNumberConditionValue = {
    type: 'number';
    value: number;
};

export type WorkflowBooleanConditionValue = {
    type: 'boolean';
    value: boolean;
};

export type WorkflowInstantConditionValue = {
    type: 'instant';
    value: string;
};

/**
 * Bounded data-only AST; depth is at most 8 and the entire tree at most 128 nodes.
 */
export type WorkflowCondition = ({
    kind: 'predicate';
} & WorkflowPredicateCondition) | ({
    kind: 'all';
} & WorkflowAllCondition) | ({
    kind: 'any';
} & WorkflowAnyCondition) | ({
    kind: 'not';
} & WorkflowNotCondition);

export type WorkflowPredicateCondition = unknown & {
    kind: 'predicate';
    field: WorkflowConditionField;
    operator: WorkflowConditionOperator;
    values: Array<WorkflowConditionValue>;
};

export type WorkflowAllCondition = {
    kind: 'all';
    children: Array<WorkflowCondition>;
};

export type WorkflowAnyCondition = {
    kind: 'any';
    children: Array<WorkflowCondition>;
};

export type WorkflowNotCondition = {
    kind: 'not';
    children: [
        WorkflowCondition
    ];
};

export type WorkflowStateAction = {
    action: WorkflowAction;
    effects: WorkflowEffectPlan;
};

export type WorkflowStateDefinition = {
    key: WorkflowStateKey;
    initial: boolean;
    terminal: boolean;
    visibility: WorkflowVisibility;
    actions: Array<WorkflowStateAction>;
};

export type WorkflowTransitionDefinition = {
    key: WorkflowTransitionKey;
    from: WorkflowStateKey;
    to: WorkflowStateKey;
    requiredComment: boolean;
    reopen: boolean;
    requiredRoles: Array<WorkflowStateKey>;
    requiredPermissions: Array<WorkflowPermission>;
    requiredCustomFields: Array<WorkflowStateKey>;
    condition?: WorkflowCondition;
    effects: WorkflowEffectPlan;
};

export type WorkflowDesign = {
    states: Array<WorkflowStateDefinition>;
    transitions: Array<WorkflowTransitionDefinition>;
};

export type WorkflowDefinition = {
    id: string;
    kind: WorkflowKind;
    version: WorkflowResourceVersion;
    initialState: WorkflowStateKey;
    states: Array<WorkflowStateDefinition>;
    transitions: Array<WorkflowTransitionDefinition>;
};

/**
 * Tenant-bound mutable catalog metadata around one current immutable published definition.
 */
export type ManagedWorkflow = {
    id: string;
    tenantId: string;
    kind: WorkflowKind;
    key: WorkflowCatalogKey;
    displayName: string;
    description: string;
    isDefault: boolean;
    status: WorkflowAdminStatus;
    revision: WorkflowResourceVersion;
    currentVersion: WorkflowResourceVersion;
    current: WorkflowDefinition;
    createdAt: string;
    updatedAt: string;
    archivedAt?: string;
};

export type WorkflowAdminPage = {
    items: Array<ManagedWorkflow>;
    nextCursor?: string;
};

export type WorkflowVersionRecord = {
    tenantId: string;
    workflowId: string;
    definition: WorkflowDefinition;
    publishedByMembershipId?: string;
    publisherDisplayName: string;
    publishedAt: string;
};

export type WorkflowVersionPage = {
    items: Array<WorkflowVersionRecord>;
    nextVersion?: WorkflowResourceVersion;
};

export type WorkflowCreateRequest = {
    kind: WorkflowKind;
    key: WorkflowCatalogKey;
    displayName: string;
    description: string;
    design: WorkflowDesign;
};

export type WorkflowPublishRequest = {
    expectedRevision: WorkflowResourceVersion;
    design: WorkflowDesign;
};

export type WorkflowMetadataRequest = {
    expectedRevision: WorkflowResourceVersion;
    displayName: string;
    description: string;
};

export type WorkflowLifecycleRequest = {
    expectedRevision: WorkflowResourceVersion;
};

/**
 * Exact immutable replay receipt; raw idempotency material is structurally absent.
 */
export type WorkflowAdminMutationResult = {
    workflow: ManagedWorkflow;
    replayed: boolean;
};

/**
 * Absence of value means presence-only; explicit null and arbitrary JSON are forbidden.
 */
export type WorkflowSimulationFact = {
    field: WorkflowConditionField;
    value?: WorkflowConditionValue;
};

export type WorkflowSimulationRequest = {
    /**
     * Zero selects the current publication; a positive value selects that exact immutable version.
     */
    version: number;
    state: WorkflowStateKey;
    commentPresent: boolean;
    roles: Array<WorkflowStateKey>;
    permissions: Array<WorkflowPermission>;
    providedCustomFields: Array<WorkflowStateKey>;
    facts: Array<WorkflowSimulationFact>;
};

export type WorkflowTransitionGates = {
    commentSatisfied: boolean;
    roleSatisfied: boolean;
    permissionsSatisfied: boolean;
    customFieldsSatisfied: boolean;
    conditionSatisfied: boolean;
};

export type WorkflowTransitionSimulation = {
    key: WorkflowTransitionKey;
    from: WorkflowStateKey;
    to: WorkflowStateKey;
    reopen: boolean;
    eligible: boolean;
    gates: WorkflowTransitionGates;
    missingRoles: Array<WorkflowStateKey>;
    missingPermissions: Array<WorkflowPermission>;
    missingCustomFields: Array<WorkflowStateKey>;
    effects: WorkflowEffectPlan;
};

/**
 * Explanatory output only. It is never an authorization proof and must not be accepted by mutation endpoints.
 */
export type WorkflowSimulationResult = {
    workflowId: string;
    kind: WorkflowKind;
    version: WorkflowResourceVersion;
    explanatory: true;
    transitions: Array<WorkflowTransitionSimulation>;
};

export type WorkflowStateKey = string;

export type WorkflowTransitionKey = string;

/**
 * Immutable workflow-version and current-state snapshot; Alert and Case kinds are never interchangeable.
 */
export type WorkflowStateProjection = {
    workflowId: string;
    kind: WorkflowKind;
    version: number;
    stateKey: WorkflowStateKey;
    initial: boolean;
    terminal: boolean;
    customerVisible: boolean;
};

export type AlertWorkflowState = WorkflowStateProjection & {
    kind?: 'alert';
};

export type CaseWorkflowState = WorkflowStateProjection & {
    kind?: 'case';
};

export type AlertCustomerWorkflowState = AlertWorkflowState & {
    customerVisible?: true;
};

export type CaseCustomerWorkflowState = CaseWorkflowState & {
    customerVisible?: true;
};

/**
 * Advisory UI hint only; execution rechecks the pinned workflow, roles, permissions, and fields against live authority.
 */
export type WorkflowActionHint = {
    transitionKey: WorkflowTransitionKey;
    targetStateKey: WorkflowStateKey;
    commentRequired: boolean;
    requiredCustomFieldKeys: Array<CustomFieldKey>;
};

export type TicketSideEffectKind = 'activity' | 'audit' | 'sla' | 'notification';

/**
 * Closed server-computed mutation plan with mandatory activity and audit plus optional SLA and notification effects; clients cannot add, remove, or authorize effects.
 */
export type TicketSideEffectPlan = unknown;

/**
 * Opaque stable position only; it never conveys tenant authority.
 */
export type Phase4Cursor = string;

export type CustomFieldObjectType = 'alert' | 'case';

export type CustomFieldProjectionSurface = 'detail' | 'list' | 'export';

export type CustomFieldDataType = 'short_text' | 'long_text' | 'integer' | 'decimal' | 'boolean' | 'date' | 'datetime' | 'duration' | 'single_select' | 'multi_select' | 'url' | 'email' | 'ip' | 'cidr' | 'user' | 'operator_team' | 'customer_contact' | 'asset_reference' | 'ioc_reference' | 'structured_json';

export type CustomFieldVisibility = {
    customer: boolean;
    operator: boolean;
};

export type CustomFieldEditPolicy = {
    customerCreate: boolean;
    customerUpdate: boolean;
    operatorCreate: boolean;
    operatorUpdate: boolean;
};

export type CustomFieldPlacement = {
    showInCreate: boolean;
    showInDetail: boolean;
    showInList: boolean;
    showInExport: boolean;
};

export type CustomFieldConstraints = {
    minimumLength?: number;
    maximumLength?: number;
    minimum?: string;
    maximum?: string;
    pattern?: string;
};

export type CustomFieldOption = {
    id: string;
    key: CustomFieldKey;
    label: string;
    position: number;
    archived: boolean;
};

/**
 * Closed definition input; data-type-specific invariants are revalidated by the backend kernel.
 */
export type CustomFieldDefinitionSpec = {
    objectType: CustomFieldObjectType;
    key: CustomFieldKey;
    label: string;
    description: string;
    dataType: CustomFieldDataType;
    required: boolean;
    nullable: boolean;
    defaultValue?: CustomFieldValue;
    constraints?: CustomFieldConstraints;
    options?: Array<CustomFieldOption>;
    visibility: CustomFieldVisibility;
    editPolicy: CustomFieldEditPolicy;
    placement: CustomFieldPlacement;
    requiredOnTransitions: Array<CustomFieldKey>;
    searchable: boolean;
    filterable: boolean;
    sortable: boolean;
    allowStructuredJson: boolean;
};

export type CustomFieldDefinitionCreateRequest = {
    definitionId: string;
    definition: CustomFieldDefinitionSpec;
};

export type CustomFieldDefinitionReplaceRequest = {
    expectedVersion: ExpectedResourceVersion;
    definition: CustomFieldDefinitionSpec;
};

export type CustomFieldDefinitionArchiveRequest = {
    objectType: CustomFieldObjectType;
    expectedVersion: ExpectedResourceVersion;
    reason: string;
};

export type CustomFieldDefinition = {
    id: string;
    tenantId: string;
    schemaVersion: number;
    archived: boolean;
    definition: CustomFieldDefinitionSpec;
};

export type CustomFieldDefinitionPage = {
    items: Array<CustomFieldDefinition>;
    nextCursor?: Phase4Cursor;
};

export type CustomFieldWritePhase = 'create' | 'update' | 'transition';

/**
 * For phase update, values is an exact replacement only across definitions that are both visible on the authorized detail projection and update-editable by the actor. Omitting one of those keys deliberately removes its value, while a present null stores explicit null. Existing values outside that editable detail projection, including hidden, non-detail, and read-only definitions, are preserved.
 */
export type CustomFieldValuesReplaceRequest = {
    expectedVersion: ExpectedResourceVersion;
    phase: CustomFieldWritePhase;
    transitionKey?: CustomFieldKey;
    values: CustomFieldValues;
};

export type CustomFieldProjectedValue = {
    key: CustomFieldKey;
    definitionId: string;
    schemaVersion: number;
    presence: 'missing' | 'null' | 'present';
    value?: CustomFieldValue;
};

export type CustomFieldProjection = {
    objectType: CustomFieldObjectType;
    objectId: string;
    definitions: Array<CustomFieldDefinition>;
    values: Array<CustomFieldProjectedValue>;
    version: number;
};

export type CustomFieldValuesResult = {
    values: Array<CustomFieldProjectedValue>;
    version: number;
};

export type CustomFieldKey = string;

/**
 * Typed custom-field value; absence, explicit null, and empty strings remain distinct inputs.
 */
export type CustomFieldValue = string | number | number | boolean | null | Array<string | number | number | boolean> | {
    [key: string]: unknown;
};

/**
 * Server validates each key against the tenant definition, object kind, schema version, visibility, and edit permission; keys are code-point sorted before idempotency binding.
 */
export type CustomFieldValues = {
    [key in CustomFieldKey]?: CustomFieldValue;
};

export type CustomFieldImportMode = 'dry_run' | 'commit';

/**
 * Omitting value preserves the current field; explicit null and the empty string remain distinct.
 */
export type CustomFieldImportFieldRequest = {
    key: CustomFieldKey;
    value?: CustomFieldValue;
};

/**
 * Field keys and target identifiers must be unique within their respective import coordinates.
 */
export type CustomFieldImportRowRequest = {
    targetId: string;
    expectedVersion: number;
    fields: Array<CustomFieldImportFieldRequest>;
};

/**
 * The aggregate field count is capped at 100000, each encoded value at 64 KiB, and the logical JSON request at 32 MiB.
 */
export type CustomFieldImportRequest = {
    objectType: CustomFieldObjectType;
    mode: CustomFieldImportMode;
    rows: Array<CustomFieldImportRowRequest>;
    retentionSeconds?: number;
};

/**
 * expectedRevision must equal the strong If-Match validator.
 */
export type CustomFieldImportCancelRequest = {
    objectType: CustomFieldObjectType;
    expectedRevision: number;
};

export type CustomFieldImportJobState = 'pending' | 'running' | 'cancellation_requested' | 'completed' | 'failed' | 'cancelled' | 'authorization_revoked' | 'expired';

/**
 * processed equals the exact sum of all ten exposed categories; succeeded combines dry-run-valid and committed, rejected combines validation-failed and definition-changed, and every terminal state has processed equal to total.
 */
export type CustomFieldImportProgress = {
    total: number;
    processed: number;
    succeeded: number;
    noChange: number;
    versionConflict: number;
    notFoundOrHidden: number;
    authorizationDenied: number;
    rejected: number;
    cancelled: number;
    authorizationRevoked: number;
    expired: number;
    internalFailure: number;
};

/**
 * This operator-safe projection excludes the manifest, definition snapshots, input values, and audit metadata.
 */
export type CustomFieldImportJob = {
    id: string;
    tenantId: string;
    requesterUserId: string;
    ownerMembershipId: string;
    objectType: CustomFieldObjectType;
    mode: CustomFieldImportMode;
    state: CustomFieldImportJobState;
    revision: number;
    attempts: number;
    progress: CustomFieldImportProgress;
    requestedAt: string;
    updatedAt: string;
    availableAt: string;
    expiresAt: string;
    terminalAt?: string;
    activeAttempt: boolean;
};

/**
 * replayed must equal X-Idempotent-Replay.
 */
export type CustomFieldImportMutationResult = {
    job: CustomFieldImportJob;
    replayed: boolean;
};

export type CustomFieldImportOutcome = 'dry_run_valid' | 'committed' | 'no_change' | 'validation_failed' | 'definition_changed' | 'version_conflict' | 'not_found_or_hidden' | 'authorization_denied' | 'cancelled' | 'authorization_revoked' | 'expired' | 'internal_failure';

export type CustomFieldImportFieldErrorCode = 'unknown' | 'visibility_denied' | 'edit_denied' | 'invalid_context' | 'malformed' | 'required' | 'null_not_allowed' | 'empty_not_allowed' | 'invalid_text' | 'invalid_integer' | 'invalid_decimal' | 'invalid_boolean' | 'invalid_date' | 'invalid_datetime' | 'invalid_option' | 'invalid_options' | 'invalid_url' | 'invalid_email' | 'invalid_ip' | 'invalid_cidr' | 'invalid_reference' | 'invalid_json' | 'invalid_type';

export type CustomFieldImportFieldError = {
    field: CustomFieldKey;
    code: CustomFieldImportFieldErrorCode;
};

export type CustomFieldImportResult = {
    sequence: number;
    targetId: string;
    expectedVersion: number;
    outcome: CustomFieldImportOutcome;
    resultingVersion: number;
    fieldErrors: Array<CustomFieldImportFieldError>;
    recordedAt: string;
};

export type CustomFieldImportResultPage = {
    items: Array<CustomFieldImportResult>;
    nextAfter?: number;
};

export type DfirStableKey = string;

export type DfirTag = string;

/**
 * Bounded to 64 KiB, 32 levels, and 4096 values by the strict transport parser.
 */
export type DfirBoundedDocument = {
    [key: string]: unknown;
};

export type DfirIndicatorType = 'ipv4' | 'ipv6' | 'domain' | 'hostname' | 'url' | 'email' | 'md5' | 'sha1' | 'sha256' | 'sha512' | 'filename' | 'registry_key' | 'process' | 'mutex' | 'cve' | 'custom';

