export type DfirTaskStatus = 'todo' | 'in_progress' | 'blocked' | 'done' | 'cancelled';

export type DfirTaskPriority = 'low' | 'medium' | 'high' | 'urgent';

export type DfirChecklistItem = {
    id: string;
    title: string;
    completed: boolean;
    completedAt?: string;
    completedBy?: string;
};

/**
 * Client intent only. Completion actor and timestamp are assigned by the server and cannot be forged.
 */
